namespace PhotoWoo.Localization;

internal static class SettingsTranslations
{
    internal static Dictionary<string, Dictionary<string, string>> Create()
    {
        string[] languages = ["en", "ru", "de", "fr", "es", "it", "pt", "pl", "uk", "zh-Hans"];
        var result = languages.ToDictionary(language => language, _ => new Dictionary<string, string>(StringComparer.Ordinal), StringComparer.Ordinal);
        foreach (var row in Table.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries))
        {
            var fields = row.Split('|');
            if (fields.Length != languages.Length + 1) throw new InvalidOperationException("Incomplete translation: " + fields[0]);
            for (var i = 0; i < languages.Length; i++) result[languages[i]].Add(fields[0], fields[i + 1].Replace("\\n", "\n"));
        }
        return result;
    }

